  .input({ vendor: z.string(), brief: z.string(), vendorOffers: z.array(z.string()) })
  .output({ move: z.enum(['counter', 'accept', 'walkAway']), message: z.string() });
const negotiator = H.agent('negotiator', negotiatorRole).model(opus).pool(api);

