      ['orders', 'accounts'].map(database =>
        to.create({ attributes: { database, night: new Date(c.now).toISOString().slice(0, 10) } }))),
  ])
  .runner(sshHosts)
  .preflight(diskSpace)
  .handler(backupFlow, { ends: { backedUp: BackedUp } });

