const local = shell.local('local', { slots: 4 });
const diskPreflight = ['test "$(df --output=avail -BG /var/backups | tail -1 | tr -dc 0-9)" -ge 20'];
const alpha = ssh.host('alpha', {
  address: 'alpha.internal',
