  .triggers(failingHeartbeatsOpenIncident, failedBackupOpensIncident, slowBackupNoted)
  .scheduler(incidentsPreempt)
  .clients(operatorApi)
  .observers(incidentAlerts, markdown.board('BOARD.md'));

